# Super Mario Bros. 3 (NES): the names this project gives to the program's
# routines, tables and variables, and what code discovery cannot recover by
# itself.
#
# The cartridge is an MMC3 board: 32 banks of 8 KiB of PRG ROM, the game in
# PRG mode 1 (bank 30 fixed at $8000, bank 31 at $E000, others switched in
# at $A000 and $C000), 8 KiB of RAM at $6000, and 128 KiB of CHR ROM in 1
# and 2 KiB banks. See src/image/rom.mbt for the syntax.

rom 959fdd32c71735d6fb2bd16a646d39f4ee65623273dd035e6a968e991bd13ef8 262144 131072 ; Super Mario Bros. 3 (USA)
prg_mode 1

# The banks, and the window each was made for. The tileset tables in bank 30
# give the levels' banks (a tileset's bank at $A000 always runs with bank 14
# at $C000); the others are from where their code jumps.
bank 0 objects $c000      ; the objects' common code
bank 1 objects1 $a000     ; objects, by group
bank 2 objects2 $a000
bank 3 objects3 $a000
bank 4 objects4 $a000
bank 5 objects5 $a000
bank 6 bank6 $a000
bank 7 bank7 $a000
bank 8 bank8 $a000
bank 9 bank9 $a000
bank 10 map $c000         ; the world map
bank 11 map_objects $a000 ; the world map's objects
bank 12 bank12 $a000
bank 13 tiles13 $a000 with 14 ; a tileset's level code and data (see tileset_a000_banks)
bank 14 levels $c000      ; level loading, for most tilesets (see tileset_c000_banks)
bank 15 tiles15 $a000 with 14
bank 16 tiles16 $a000 with 14
bank 17 tiles17 $a000 with 14
bank 18 tiles18 $a000 with 14
bank 19 tiles19 $a000 with 14
bank 20 tiles20 $a000 with 14
bank 21 tiles21 $a000 with 14
bank 22 levels22 $c000    ; level loading for the last tilesets
bank 23 tiles23 $a000 with 14
bank 24 title $a000       ; the title screen
bank 25 bank25 $a000
bank 26 status $a000      ; the status bar, from the NMI
bank 27 bank27 $a000
bank 28 sound $a000       ; the sound engine
bank 29 music $c000
bank 30 fixed_8000        ; fixed at $8000
bank 31 fixed_e000        ; fixed at $E000

# The interrupt handlers check the cartridge's RAM signature and, when it is
# gone, jump through the reset vector: a path a working cartridge never
# takes.
trap $f7a3 ; the IRQ handler finds the RAM signature gone

# Branches always taken where discovery cannot tell
trap 2:$a7f5  ; lda $7f,x / eor #1 / tay / bpl: the direction is 0 or 1
trap 28:$a709 ; ora #$10 / bne

# The game keeps the banks it wants in RAM and switches from there (lda
# #bank / sta $0720 / jsr $ffc2): where nothing else tells, the windows
# hold these.
shadow $a000 $0720
shadow $c000 $071f

# Variables

var $0100 nmi_mode              ; which NMI handler runs (and IRQ handler, $0101)
var $0101 irq_mode
var $070a level_tileset         ; the kind of level (0: the world map)
var $0719 chr_banks 6           ; the CHR banks the NMI maps (R0-R5)
var $071f bank_c000             ; the bank wanted at $C000
var $0720 bank_a000             ; the bank wanted at $A000
var $0721 bank_select           ; MMC3's bank select last written

# Fixed bank 30 ($8000)

table $83d6 tileset_c000_banks 19 ; by level_tileset
table $83e9 tileset_a000_banks 19 ; by level_tileset

# Jump tables: the code addresses after each call to jump_by_index
# ($fe99), by the index in A

routine $fe99 jump_by_index     ; jump to the A-th code address after the call
